import { readFile } from "node:fs/promises";
import { put } from "@tigrisdata/storage";

async function main() {
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim();
  const bucketName = `harbor-interop-${trialId.toLowerCase().replace(/_/g, '-')}`;

  const body = JSON.stringify({ created_by: "cli", modified_by: "sdk", trial: trialId });

  const { data, error } = await put("manifest.json", body, {
    contentType: "application/json",
    config: { bucket: bucketName },
  });

  if (error) {
    console.error("upload failed:", error);
    process.exit(1);
  }
  console.log("uploaded", data);
}

main().catch(console.error);
